package store

type Todo struct {
	ID     int
	Title  string
	Status string // "open" or "done"
}

type Store struct {
	todos []Todo
}

func New() *Store {
	return &Store{}
}

func (s *Store) Add(title string) Todo {
	t := Todo{ID: len(s.todos) + 1, Title: title, Status: "open"}
	s.todos = append(s.todos, t)
	return t
}

func (s *Store) All() []Todo {
	out := make([]Todo, len(s.todos))
	copy(out, s.todos)
	return out
}

test_setup_files.query_hidden_test.go:
package store

import "testing"

func titles(ts []Todo) []string {
	out := make([]string, len(ts))
	for i, t := range ts {
		out[i] = t.Title
	}
	return out
}

// White-box: this test file lives in `package store`, so it can reach the
// unexported todos slice directly to seed a REALISTIC interleaved status
// pattern - Store has no setter to mark an item done, but the whole point
// of this test is to distinguish filter-before-paginate from
// paginate-before-filter, which is invisible if every item shares one
// status (paginating an all-open store gives identical pages either way).
func TestQueryPaginatesWithinTheFilteredSet(t *testing.T) {
	s := New()
	// done, open, done, open, open, done, open  (interleaved on purpose)
	pattern := []string{"done", "open", "done", "open", "open", "done", "open"}
	for i, status := range pattern {
		s.Add("item" + string(rune('1'+i)))
		s.todos[i].Status = status
	}
	// open items, in store order: item2, item4, item5, item7

	page1 := s.Query("open", 0, 2)
	page2 := s.Query("open", 2, 2)
	page3 := s.Query("open", 4, 2)

	if got := titles(page1); len(got) != 2 || got[0] != "item2" || got[1] != "item4" {
		t.Fatalf("page1 = %v, want [item2 item4]", got)
	}
	if got := titles(page2); len(got) != 2 || got[0] != "item5" || got[1] != "item7" {
		t.Fatalf("page2 = %v, want [item5 item7]", got)
	}
	if got := titles(page3); len(got) != 0 {
		t.Fatalf("page3 = %v, want []", got)
	}
}

func TestQueryEmptyStatusMeansNoFilter(t *testing.T) {
	s := New()
	s.Add("a")
	s.Add("b")
	s.Add("c")

	got := s.Query("", 0, 10)
	if len(got) != 3 {
		t.Fatalf("Query('', ...) = %d items, want 3", len(got))
	}
}

func TestQueryOffsetBeyondMatchesIsEmpty(t *testing.T) {
	s := New()
	s.Add("a")
	got := s.Query("open", 5, 10)
	if len(got) != 0 {
		t.Fatalf("offset beyond matches should be empty, got %d", len(got))
	}
}

