package store

type Todo struct {
	ID     int
	Title  string
	Status string // "open" or "done"
}

type Store struct {
	todos []Todo
}

func New() *Store {
	return &Store{}
}

func (s *Store) Add(title string) Todo {
	t := Todo{ID: len(s.todos) + 1, Title: title, Status: "open"}
	s.todos = append(s.todos, t)
	return t
}

func (s *Store) All() []Todo {
	out := make([]Todo, len(s.todos))
	copy(out, s.todos)
	return out
}

// Query filters by status ("" means no filter) and returns at most `limit`
// results starting after skipping `offset` MATCHING items, preserving Add
// order. offset/limit apply to the FILTERED set, not the whole store.
func (s *Store) Query(status string, offset, limit int) []Todo {
	var matched []Todo
	for _, t := range s.todos {
		if status == "" || t.Status == status {
			matched = append(matched, t)
		}
	}
	if offset >= len(matched) {
		return []Todo{}
	}
	end := offset + limit
	if end > len(matched) || limit < 0 {
		end = len(matched)
	}
	out := make([]Todo, end-offset)
	copy(out, matched[offset:end])
	return out
}

