package store

type Todo struct {
	ID     int
	Title  string
	Status string // "open" or "done"
}

type Store struct {
	todos []Todo
}

func New() *Store {
	return &Store{}
}

func (s *Store) Add(title string) Todo {
	t := Todo{ID: len(s.todos) + 1, Title: title, Status: "open"}
	s.todos = append(s.todos, t)
	return t
}

func (s *Store) All() []Todo {
	out := make([]Todo, len(s.todos))
	copy(out, s.todos)
	return out
}

func (s *Store) Query(status string, offset, limit int) []Todo {
	end := offset + limit
	if end > len(s.todos) || limit < 0 {
		end = len(s.todos)
	}
	if offset >= len(s.todos) {
		return []Todo{}
	}
	page := s.todos[offset:end]

	var out []Todo
	for _, t := range page {
		if status == "" || t.Status == status {
			out = append(out, t)
		}
	}
	return out
}
